  let crc16 = 0x0;

  for (let i = 0; i < payload.length; i += 1) {
    const byte = payload[i];
    if (byte === undefined) {
      continue;
    }

    const lookupIndex = (crc16 >> 8) ^ byte;
    crc16 = (crc16 << 8) ^ (crcTable[lookupIndex] ?? 0);
    crc16 &= 0xffff;
  }
  const checksum = new Uint8Array(2);
  checksum[0] = crc16 & 0xff;
  checksum[1] = (crc16 >> 8) & 0xff;
  return checksum;
}

