import { MethodTable } from "@site/src/components/MethodTable";

<MethodTable>

|     |                                                                    |
| --- | ------------------------------------------------------------------ |
| GET | `/{endpoint}?cursor={paging_token}&order={asc,desc}&limit={1-200}` |

</MethodTable>

<AttributeTable>

- ARGUMENT
  - REQUIRED?
  - DESCRIPTION
- cursor
  - optional
  - A number that points to a specific location in a collection of responses and is pulled from the `paging_token` value of a record.
- order
  - optional
  - A designation of the order in which records should appear. Options include `asc`(ascending) or `desc` (descending). If this argument isn’t set, it defaults to `asc`.
- limit
  - optional
  - The maximum number of records returned. The limit can range from 1 to 200 - an upper limit that is hardcoded in Horizon for performance reasons. If this argument isn’t designated, it defaults to 10.

</AttributeTable>

<CodeExample title="Example Request">

```curl
curl "https://horizon-testnet.stellar.org/ledgers/26478723/operations?cursor=113725249324879872&limit=5&order=asc"
```

```js
var StellarSdk = require("@stellar/stellar-sdk");
var server = new StellarSdk.Horizon.Server(
  "https://horizon-testnet.stellar.org",
);

server
  .operations()
  .forLedger("26478723")
  .cursor("113725249324879872")
  .limit(5)
  .order("asc")
  .call()
  .then(function (resp) {
    console.log(resp);
  })
  .catch(function (err) {
    console.error(err);
  });
```

